package gen_test

import (
	"strings"
	"testing"

	"github.com/cptaffe/automaton/lex"
	"github.com/cptaffe/automaton/lex/gen"
)

func TestTheTableIsGo(t *testing.T) {
	spec := build(t, "start {\n  [a-z]+ do name emit word\n  \" \" ignore\n  \"(\" emit open-paren -> inner\n}\n\ninner {\n  \")\" emit close.paren -> start\n}\n")
	src, err := gen.Go(spec, "scan", "t.lex")

	if err != nil {
		t.Fatal(err)
	}

	for _, want := range []string{
		"// Code generated by genlex from t.lex. DO NOT EDIT.",
		"package scan",
		"TokCloseParen = 1",
		"TokOpenParen  = 2",
		"TokWord       = 3",
		"DoName = 1",
		`Does:   []string{"name"}`,
		"{Emit: 2, Goto: 2}",
		"{},",
	} {
		if !strings.Contains(string(src), want) {
			t.Errorf("the table does not hold %q:\n%s", want, src)
		}
	}
}

func TestTheTableRefusesBadNames(t *testing.T) {
	for _, c := range []struct {
		spec lex.Spec
		pkg  string
		want string
	}{
		{lex.Spec{}, "", `"" cannot name a package`},
		{lex.Spec{Tokens: []string{"a-b", "aB"}}, "scan", "a-b and aB are both TokAB in Go"},
		{lex.Spec{Tokens: []string{"-"}}, "scan", "- cannot name a Go constant"},
	} {
		if _, err := gen.Go(&c.spec, c.pkg, "t.lex"); err == nil || !strings.Contains(err.Error(), c.want) {
			t.Errorf("the refusal is %v; want %q", err, c.want)
		}
	}
}

func TestTheBlankPackageIsNoPackage(t *testing.T) {
	if _, err := gen.Go(&lex.Spec{}, "_", "t.lex"); err == nil {
		t.Error("package _ was written")
	}
}
